// 8 requêtes ciblées agences SEA/performance France
// site:linkedin.com/in = Google cherche dans les profils LinkedIn publics (pas de scraping LinkedIn)
return [
  { json: { query: 'site:linkedin.com/in "fondateur" "agence Google Ads" France -freelance', label: 'Google Ads' } },
  { json: { query: 'site:linkedin.com/in "CEO" OR "co-fondateur" "agence SEA" France -freelance', label: 'SEA' } },
  { json: { query: 'site:linkedin.com/in "fondateur" "agence performance" "Google Ads" France', label: 'Performance' } },
  { json: { query: 'site:linkedin.com/in "fondateur" "Meta Ads" OR "Facebook Ads" agence France -freelance', label: 'Meta Ads' } },
  { json: { query: 'site:linkedin.com/in "fondateur" "paid social" agence France -freelance', label: 'Paid Social' } },
  { json: { query: 'site:linkedin.com/in "fondateur" "Google Premier Partner" agence France', label: 'Premier Partner' } },
  { json: { query: 'site:linkedin.com/in "fondateur" "agence acquisition" OR "lead generation" "Google Ads" France', label: 'Acquisition' } },
  { json: { query: 'site:linkedin.com/in "fondateur" "media buying" OR "achat media" agence France -freelance', label: 'Media Buying' } }
];

// Extrait les profils LinkedIn des résultats Serper
// Accumule dans staticData pour collecter sur toutes les requêtes
const staticData = $getWorkflowStaticData('global');
if (!staticData.allProfiles) staticData.allProfiles = [];

const data = $input.item.json;
const results = data.organic || [];
const label = $('Boucle requêtes').item.json.label || 'search';

for (const r of results) {
  const title = r.title || '';
  const link = r.link || '';
  const snippet = r.snippet || '';

  // Garder uniquement les URLs linkedin.com/in (profils personnels)
  if (!link.includes('linkedin.com/in')) continue;

  // Parsing du titre Google : "Prénom Nom - Poste - Agence | LinkedIn"
  const parts = title.split(' - ');
  const nom = parts[0]?.trim() || '';
  const poste = parts[1]?.trim() || '';
  let agence = parts[2]?.replace(/\|.*$/, '').trim() || '';

  // Ignorer si pas de nom ou trop court
  if (!nom || nom.length < 3) continue;

  // Ignorer les mots-clés IA/automation dans le snippet
  const blacklist = ['automatisation', 'no-code', 'make.com', 'zapier', 'n8n', 'automation agency'];
  const snippetLower = snippet.toLowerCase();
  if (blacklist.some(w => snippetLower.includes(w))) continue;

  staticData.allProfiles.push({
    nom,
    poste,
    agence,
    linkedin_url: link,
    snippet: snippet.substring(0, 200),
    source: label
  });
}

console.log(`Profils accumulés : ${staticData.allProfiles.length}`);
return [{ json: { profils_accumules: staticData.allProfiles.length } }];

// Récupère tous les profils accumulés, déduplique par URL LinkedIn
const staticData = $getWorkflowStaticData('global');
const all = staticData.allProfiles || [];
staticData.allProfiles = []; // reset pour la prochaine exécution

const seen = new Set();
const unique = all.filter(p => {
  if (!p.linkedin_url || seen.has(p.linkedin_url)) return false;
  seen.add(p.linkedin_url);
  return true;
});

console.log(`Profils uniques après déduplication : ${unique.length}`);
return [{ json: { profiles: unique, total: unique.length } }];

// Parse la réponse Claude et sépare qualifiés / éliminés
const response = $input.item.json;
if (!response.content?.[0]?.text) {
  throw new Error('Réponse Claude invalide : ' + JSON.stringify(response).substring(0, 200));
}

let raw = response.content[0].text.trim();
// Nettoyer les backticks si Claude les ajoute
if (raw.startsWith('```')) {
  raw = raw.replace(/```json?\n?/g, '').replace(/```$/g, '').trim();
}

let evaluated;
try {
  evaluated = JSON.parse(raw);
} catch (e) {
  throw new Error('JSON invalide de Claude : ' + raw.substring(0, 300));
}

const qualifies = evaluated.filter(p => p.qualifie === true);
const elimines = evaluated.filter(p => p.qualifie === false);

console.log(`ICP SEA : ${qualifies.length} qualifiés / ${elimines.length} éliminés`);
console.log('Éliminés :', elimines.map(p => `${p.nom} (${p.raison_elimination})`).join(', '));

return [{ json: { qualifies, total_evalues: evaluated.length, total_qualifies: qualifies.length } }];

// Convertit le tableau de qualifiés en items séparés
const d = $input.item.json;
const qualifies = d.qualifies || [];

if (qualifies.length === 0) {
  return [{ json: { message: 'Aucun prospect SEA qualifié cette session', total: 0 } }];
}

console.log(`${qualifies.length} prospects SEA qualifiés à insérer dans le CRM`);
return qualifies.map(p => ({ json: p }));

// Prépare la query Notion pour vérifier si le prospect existe déjà
const p = $input.item.json;
return [{ json: {
  notion_query: JSON.stringify({
    filter: {
      or: [
        { property: 'Nom', title: { contains: p.nom || '' } },
        { property: 'LinkedIn', url: { contains: (p.linkedin_url || '').replace('https://www.', 'https://') } }
      ]
    },
    page_size: 1
  }),
  prospect: p
}}];

// Construit le body Notion qui correspond exactement au schéma du CRM Prospection LinkedIn
const p = $('Boucle prospects').item.json;

// Notes avec contexte source
const notes = [
  p.source ? `Source requête : ${p.source}` : '',
  p.snippet ? p.snippet.substring(0, 300) : ''
].filter(Boolean).join(' | ');

return [{ json: {
  notion_body: JSON.stringify({
    parent: { database_id: 'REMPLACER_PAR_ID_DB_NOTION' },
    properties: {
      'Nom': {
        title: [{ text: { content: p.nom || '' } }]
      },
      'Agence': {
        rich_text: [{ text: { content: p.agence || '' } }]
      },
      'Rôle': {
        rich_text: [{ text: { content: p.poste || '' } }]
      },
      'LinkedIn': {
        url: p.linkedin_url || null
      },
      'Statut': {
        select: { name: 'À envoyer' }
      },
      'Canal': {
        select: { name: 'InMail' }
      },
      'Douleur': {
        select: { name: p.douleur_probable || 'P-MON — Monitoring' }
      },
      'Liste': {
        select: { name: p.liste || 'B-list' }
      },
      'Notes': {
        rich_text: [{ text: { content: notes.substring(0, 1900) } }]
      }
    }
  })
}}];

const items = $input.all();
const ts = new Date().toISOString();
console.log(`P-DISCOVERY-SEA terminé — ${ts}`);
return [{ json: { status: 'done', timestamp: ts, message: 'Session Discovery SEA terminée. Vérifie le CRM Notion.' } }];
